<?php declare(strict_types=1); namespace Annam; $seller=$invoice['seller'];$buyer=$invoice['buyer'];$credit=$invoice['kind']==='credit_note';$taxRegistered=$invoice['kind']==='tax_invoice'||($seller['gst_mode']??'')==='regular';$labels=['bill'=>'Bill','tax_invoice'=>'Tax invoice','bill_of_supply'=>'Bill of supply','credit_note'=>'Credit note'];$address=$buyer['delivery_address']??[];$logo=image_url($seller['logo_url']??'');if(($seller['logo_url']??'')==='/static/branding/annam-bill-logo.png')$logo='/media/brand/annam-bill-logo.png'; ?>
<?php $payment=(new Billing($store))->paymentState($invoice);$requestPath=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$staffBill=str_starts_with($requestPath,'/billing/')||str_starts_with($requestPath,'/manage/');
$receipt_back=$receipt_back??'';$receipt_download=$receipt_download??'';
if($staffBill){$manage=str_starts_with($requestPath,'/manage/');$receipt_back=!empty($invoice['order_id'])?($manage?'/manage/orders/':'/billing/orders/').$invoice['order_id'].'/':($manage?'/manage/':'/billing/');$receipt_download=($manage?'/manage/bills/':'/billing/bills/').$invoice['id'].'/download/';}
$badgeClass=$credit?'af-receipt-credit':($payment['payment_refunded']?'af-receipt-refunded':(!$payment['payment_received']?'af-receipt-unpaid':'')); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= e($invoice['number']) ?> · <?= e($seller['name']) ?></title><link rel="stylesheet" href="<?= e(asset_url('receipt.css')) ?>"></head><body><article class="af-receipt"><header class="af-receipt-head"><?php if($logo): ?><img class="af-receipt-logo" src="<?= e($logo) ?>" alt="<?= e($seller['name']) ?> logo"><?php endif; ?><h2><?= e($seller['name']) ?></h2><p class="af-receipt-tagline"><?= e($seller['tagline']??'') ?></p><?php if($invoice['kind']!=='bill'): ?><h3 class="af-document-title"><?= e($labels[$invoice['kind']]??'Bill') ?></h3><?php endif; ?><span class="af-receipt-badge <?= e($badgeClass) ?>"><?= $credit?'Credit note issued':($payment['payment_received']?'✓ Payment received':($payment['payment_refunded']?'Payment refunded':'UNPAID — payment not received')) ?></span></header>
<dl class="af-receipt-meta"><?php foreach(['Bill number'=>$invoice['number'],'Issued'=>date('j M Y, g:i A',strtotime($invoice['issued_at'])),'Order / meal'=>($buyer['order_no']??'').' · '.($buyer['slot']??'')] as $label=>$value): ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl>
<?php if($credit&&!empty($payment['original_number'])): ?><p>Original bill: <?= e($payment['original_number']) ?></p><?php endif; ?><section class="af-receipt-customer"><h3>Customer & delivery</h3><p class="af-customer-name"><?= e($buyer['name']??'') ?></p><p><?= e($buyer['phone']??'') ?></p><?php foreach(['business_name','billing_address','gstin'] as $key): if(!empty($buyer[$key])): ?><p><?= nl2br(e($buyer[$key])) ?></p><?php endif; endforeach; ?><p class="af-delivery-address"><?= e(($address['fulfilment']??'')==='Collection'?'Collection':implode(', ',array_unique(array_filter(array_map(fn($key)=>$address[$key]??'', ['line1','line2','landmark','area','city','state','country','pincode']))))) ?></p><?php if($buyer['delivery_date']??''): ?><p>Delivery: <?= e(date('j M Y',strtotime($buyer['delivery_date']))) ?></p><?php endif; ?></section>
<table class="af-receipt-items"><thead><tr><th><?= $credit?'Credited items':'Your order' ?></th><th>Amount</th></tr></thead><tbody><?php foreach($invoice['lines'] as $line): ?><tr><td><strong><?= e($line['description']) ?></strong><span class="af-item-detail"><?= e($line['quantity']) ?> × <?= money((string)$line['unit_price']) ?><?php if(!empty($line['sac'])): ?><span class="af-item-sac"> · SAC / HSN: <?= e($line['sac']) ?></span><?php endif; ?></span><?php if($taxRegistered): ?><span class="af-item-detail">Taxable: <?= money((string)$line['taxable']) ?> · GST <?= e($line['tax_rate']) ?>%: <?= money((string)$line['tax']) ?></span><?php endif; ?></td><td><?= Money::display(Money::parse((string)$line['taxable'])+Money::parse((string)$line['tax'])) ?></td></tr><?php endforeach; ?></tbody></table>
<dl class="af-receipt-summary"><div><dt><?= $taxRegistered?'Taxable value':'Subtotal' ?></dt><dd><?= money($invoice['taxable']) ?></dd></div><?php if($taxRegistered): foreach(['cgst','sgst','igst'] as $key): ?><div><dt><?= e(strtoupper($key)) ?></dt><dd><?= money($invoice[$key]) ?></dd></div><?php endforeach; endif; ?><div><dt>Round off</dt><dd>₹<?= e($invoice['round_off']) ?></dd></div></dl><div class="af-receipt-total"><span><?= $credit?'Credit total':($payment['payment_refunded']?'Original total':($payment['payment_received']?'Total paid':'Total payable')) ?></span><strong><?= money($invoice['total']) ?></strong></div><?php if(!$credit&&!$payment['payment_received']&&!$payment['payment_refunded']): ?><p class="af-receipt-notice af-receipt-due"><strong>Amount due: <?= money($payment['amount_due']) ?> — payment not received</strong></p><?php endif; ?><p class="af-receipt-words"><?= e($invoice['amount_words']) ?></p><div class="af-receipt-payment"><?php if(!$credit): ?><p>Payment: <?= e(['manual'=>'Manual payment','cod'=>'Cash on delivery','online'=>'Online payment'][$invoice['payment_mode']]??$invoice['payment_mode']) ?></p><?php endif; ?><?php if($credit?$invoice['payment_ref']:$payment['settlement_reference']): ?><p><?= $credit?'Reason':'Reference' ?>: <?= e($credit?$invoice['payment_ref']:$payment['settlement_reference']) ?></p><?php endif; ?></div>
<?php if(($seller['gst_mode']??'')==='composition'): ?><p class="af-receipt-notice">Composition taxable person, not eligible to collect tax on supplies.</p><?php endif; ?><?php if($buyer['courier_deferred']??false): ?><p class="af-receipt-notice"><?= e(Delivery::COURIER) ?></p><?php endif; ?><footer class="af-receipt-footer"><?php if(!$credit): ?><h3>Thank you for ordering with us!</h3><?php endif; ?><p><?= nl2br(e($seller['footer']??'')) ?></p><p class="af-receipt-signature">Authorised signatory</p><div class="af-receipt-legal"><p><strong><?= e($seller['name']) ?></strong> · <?= nl2br(e($seller['address'])) ?></p><p><?= e($seller['state'].' · State code '.$seller['state_code']) ?><br>FSSAI: <?= e($seller['fssai_no']) ?><?php if($seller['gstin']): ?><br>GSTIN: <?= e($seller['gstin']) ?><?php endif; ?></p></div></footer></article><div class="bill-actions"><button id="print-bill">Print / Save PDF</button><?php if($receipt_download): ?><a href="<?= e($receipt_download) ?>">Download PDF</a><?php endif; ?><a href="<?= e($receipt_back?:'/') ?>"><?= $receipt_back?'Back to order':'Home' ?></a><?php if($staffBill&&!$credit): ?><a href="/billing/new/?channel=<?= strtolower((string)($buyer['channel']??''))==='whatsapp'?'whatsapp':'manual' ?>">New booking</a><?php endif; ?></div><script src="<?= e(asset_url('print.js')) ?>" defer></script></body></html>
